<script setup lang="ts">
import { computed, ref } from 'vue';
import type { OasRequirement } from '../domain/models';
import { change, state, scope, ui } from '../state';
import { recordFor, requiredTimes, occurrenceState } from '../domain/progress';
import { validateRequirements } from '../domain/requirements';
const props=defineProps<{requirement:OasRequirement}>();
const hideComplete=ref(false),editing=ref(false),text=ref('');
const scouts=computed(()=>scope.value.filter(s=>!hideComplete.value||!recordFor(state.value!.progress.scoutRecords,s,props.requirement.id).completed));
function complete(scout:string,value:boolean){change('Before completion change',s=>{const key=scout+'::'+props.requirement.id;s.progress.scoutRecords[key]={...recordFor(s.progress.scoutRecords,scout,props.requirement.id),completed:value,date:value?new Date().toISOString().slice(0,10):'',source:'manual'};});}
function save(){try{const next=JSON.parse(text.value) as OasRequirement;if(next.id!==props.requirement.id)throw new Error('Existing requirement IDs cannot be changed.');if(change('Before requirement edit',s=>{s.requirements=s.requirements.map(r=>r.id===next.id?next:r);validateRequirements(s.requirements);})){editing.value=false;}}catch(e){ui.error=String(e);}}
</script>
<template><aside class="detail"><button class="close" aria-label="Close requirement details" @click="ui.requirementId=''">×</button><small>{{requirement.id}} · Stage {{requirement.stage}} · {{requirement.stream}}</small><h2>{{requirement.text}}</h2><p>{{requirement.workflow}} · {{requirement.tags.join(', ')}}</p><h3>Mandatory prerequisites</h3><p v-if="requirement.stage===1">Stage 1 has no readiness prerequisites.</p><button v-for="id in requirement.prerequisites" :key="id" @click="ui.requirementId=id">{{id}}</button><p v-if="!requirement.prerequisites.length">None</p><h3>Recommended links</h3><button v-for="link in requirement.suggested_links" :key="link.id" :title="link.reason" @click="ui.requirementId=link.id">{{link.id}}</button><p>Target: {{requiredTimes(requirement)}} {{requirement.occurrence_unit||'occurrence(s)'}}. Scheduled opportunities do not award completion.</p><h3>Scout evidence</h3><label class="check"><input v-model="hideComplete" type="checkbox">Hide completed Scouts</label><p v-if="!scope.length">Add or select Scouts to record evidence.</p><article v-for="scout in scouts" :key="scout" class="evidence"><label class="check"><input type="checkbox" :checked="recordFor(state!.progress.scoutRecords,scout,requirement.id).completed" @change="complete(scout,($event.target as HTMLInputElement).checked)">{{scout}}</label><small>{{occurrenceState(recordFor(state!.progress.scoutRecords,scout,requirement.id),requirement)}} / {{requiredTimes(requirement)}} · {{recordFor(state!.progress.scoutRecords,scout,requirement.id).date}} · {{recordFor(state!.progress.scoutRecords,scout,requirement.id).source}}</small><details><summary>Stored evidence</summary><pre>{{JSON.stringify(recordFor(state!.progress.scoutRecords,scout,requirement.id),null,2)}}</pre></details></article><h3>Linked activities</h3><p v-for="a in state!.progress.activities?.filter(a=>a.covers.includes(requirement.id))" :key="a.id">{{a.title||a.name||a.id}}</p><button @click="editing=!editing;text=JSON.stringify(requirement,null,2)">Edit requirement fields</button><form v-if="editing" @submit.prevent="save"><p>All metadata is editable; the ID stays fixed. Mandatory cycles and missing links are rejected.</p><label>Requirement JSON<textarea v-model="text" rows="20" /></label><button>Save requirement</button></form></aside></template>
